#include <algorithm>
#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <numeric>
#include <variant>
#include <vector>

// The settings of each filter, one struct per filter. The two limits of a Clamp are set by
// name, and an Offset is not a Scale, so neither pair can be swapped by accident. All three
// versions below take the same structs.
struct Clamp {
  int min_mm;
  int max_mm;
};
struct Offset {
  int mm;
};
struct Scale {
  int percent;
};

// 1. An interface and one class per filter.
class Filter {
 public:
  Filter() = default;
  Filter(const Filter&) = delete;
  Filter& operator=(const Filter&) = delete;
  virtual ~Filter() = default;
  [[nodiscard]] virtual int apply(int mm) const = 0;
};

class ClampFilter final : public Filter {
 public:
  explicit ClampFilter(Clamp limits) : limits_(limits) {}
  [[nodiscard]] int apply(int mm) const override { return std::clamp(mm, limits_.min_mm, limits_.max_mm); }

 private:
  Clamp limits_;
};

class OffsetFilter final : public Filter {
 public:
  explicit OffsetFilter(Offset offset) : offset_(offset) {}
  [[nodiscard]] int apply(int mm) const override { return mm + offset_.mm; }

 private:
  Offset offset_;
};

class ScaleFilter final : public Filter {
 public:
  explicit ScaleFilter(Scale scale) : scale_(scale) {}
  [[nodiscard]] int apply(int mm) const override { return mm * scale_.percent / 100; }

 private:
  Scale scale_;
};

[[nodiscard]] int run(const std::vector<std::unique_ptr<Filter>>& chain, int mm) {
  return std::accumulate(chain.begin(), chain.end(), mm, [](int acc, const auto& f) { return f->apply(acc); });
}

// 2. One callable per filter.
[[nodiscard]] int run(const std::vector<std::function<int(int)>>& chain, int mm) {
  return std::accumulate(chain.begin(), chain.end(), mm, [](int acc, const auto& f) { return f(acc); });
}

// 3. The same plain data, and a closed set of alternatives.
using AnyStep = std::variant<Clamp, Offset, Scale>;

template <typename... Fs>
struct overloaded : Fs... {
  using Fs::operator()...;
};

[[nodiscard]] int apply(const AnyStep& step, int mm) {
  return std::visit(overloaded{
                        [mm](const Clamp& c) { return std::clamp(mm, c.min_mm, c.max_mm); },
                        [mm](const Offset& o) { return mm + o.mm; },
                        [mm](const Scale& s) { return mm * s.percent / 100; },
                    },
                    step);
}

[[nodiscard]] int run(const std::vector<AnyStep>& chain, int mm) {
  return std::accumulate(chain.begin(), chain.end(), mm, [](int acc, const AnyStep& s) { return apply(s, acc); });
}

int main() {
  std::vector<std::unique_ptr<Filter>> objects;
  objects.push_back(std::make_unique<OffsetFilter>(Offset{.mm = -30}));
  objects.push_back(std::make_unique<ScaleFilter>(Scale{.percent = 110}));
  objects.push_back(std::make_unique<ClampFilter>(Clamp{.min_mm = 100, .max_mm = 5000}));

  const std::vector<std::function<int(int)>> callables{
      [offset = Offset{.mm = -30}](int mm) { return mm + offset.mm; },
      [scale = Scale{.percent = 110}](int mm) { return mm * scale.percent / 100; },
      [limits = Clamp{.min_mm = 100, .max_mm = 5000}](int mm) { return std::clamp(mm, limits.min_mm, limits.max_mm); },
  };

  const std::vector<AnyStep> steps{Offset{.mm = -30}, Scale{.percent = 110}, Clamp{.min_mm = 100, .max_mm = 5000}};

  std::cout << "reading  interface  function  variant\n";
  for (const int mm : {-50, 400, 5200}) {
    std::cout << std::format("{:>7}  {:>9}  {:>8}  {:>7}\n", mm, run(objects, mm), run(callables, mm), run(steps, mm));
  }
  std::cout << std::format("sizeof element: unique_ptr {}, function {}, variant {}\n", sizeof(objects.front()),
                           sizeof(callables.front()), sizeof(steps.front()));
  std::cout << std::format("sizeof each object behind a unique_ptr: {}, {}, {}\n", sizeof(OffsetFilter),
                           sizeof(ScaleFilter), sizeof(ClampFilter));
}

