#include <algorithm>
#include <concepts>
#include <format>
#include <iostream>
#include <memory>
#include <numeric>
#include <utility>
#include <vector>

struct Clamp {
  int min_mm;
  int max_mm;
  [[nodiscard]] int apply(int mm) const { return std::clamp(mm, min_mm, max_mm); }
};
struct Offset {
  int mm;
  [[nodiscard]] int apply(int reading_mm) const { return reading_mm + mm; }
};
struct Scale {
  int percent;
  [[nodiscard]] int apply(int mm) const { return mm * percent / 100; }
};

template <typename F>
concept RangeFilter = std::copy_constructible<F> && requires(const F& f, int mm) {
  { f.apply(mm) } -> std::same_as<int>;
};

class AnyFilter {
 public:
  // Implicit on purpose, like std::function: a Clamp converts to an AnyFilter.
  template <RangeFilter F>
  AnyFilter(F filter) : self_(std::make_unique<Model<F>>(std::move(filter))) {}

  AnyFilter(const AnyFilter& other) : self_(other.self_->clone()) {}
  AnyFilter& operator=(const AnyFilter& other) {
    self_ = other.self_->clone();  // clone first: if it throws, *this is unchanged
    return *this;
  }
  AnyFilter(AnyFilter&&) noexcept = default;
  AnyFilter& operator=(AnyFilter&&) noexcept = default;
  ~AnyFilter() = default;

  [[nodiscard]] int apply(int mm) const { return self_->apply(mm); }

 private:
  class Concept {
   public:
    Concept() = default;
    Concept(const Concept&) = delete;
    Concept& operator=(const Concept&) = delete;
    virtual ~Concept() = default;
    [[nodiscard]] virtual int apply(int mm) const = 0;
    [[nodiscard]] virtual std::unique_ptr<Concept> clone() const = 0;
  };

  template <typename F>
  class Model final : public Concept {
   public:
    explicit Model(F filter) : filter_(std::move(filter)) {}
    [[nodiscard]] int apply(int mm) const override { return filter_.apply(mm); }
    [[nodiscard]] std::unique_ptr<Concept> clone() const override { return std::make_unique<Model>(filter_); }

   private:
    F filter_;
  };

  std::unique_ptr<Concept> self_;
};

static_assert(std::constructible_from<AnyFilter, Clamp>);
static_assert(!std::constructible_from<AnyFilter, int>);

[[nodiscard]] int run(const std::vector<AnyFilter>& chain, int mm) {
  return std::accumulate(chain.begin(), chain.end(), mm, [](int acc, const AnyFilter& f) { return f.apply(acc); });
}

int main() {
  const std::vector<AnyFilter> chain{Offset{.mm = -30}, Scale{.percent = 110}, Clamp{.min_mm = 100, .max_mm = 5000}};
  std::vector<AnyFilter> halved = chain;  // copies every filter
  halved[1] = Scale{.percent = 50};       // changes the copy only

  AnyFilter spare = Offset{.mm = 10};
  const AnyFilter backup = spare;  // a non-const lvalue: still the copy constructor

  std::cout << std::format("chain:  400 -> {}\n", run(chain, 400));
  std::cout << std::format("halved: 400 -> {}\n", run(halved, 400));
  std::cout << std::format("backup: 400 -> {}\n", backup.apply(400));
  std::cout << std::format("sizeof(AnyFilter) = {}\n", sizeof(AnyFilter));
}

#include <cstddef>
#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <type_traits>

// True when the std::function keeps the callable inside its own bytes.
template <typename F>
[[nodiscard]] bool stored_inside(const std::function<int(int)>& f) {
  const auto* target = reinterpret_cast<const std::byte*>(f.target<std::remove_cvref_t<F>>());
  const auto* begin = reinterpret_cast<const std::byte*>(&f);
  return target != nullptr && !std::less<>{}(target, begin) && std::less<>{}(target, begin + sizeof f);
}

int main() {
  const auto small = [offset = 30](int mm) { return mm + offset; };
  const auto medium = [a = 1, b = 2, c = 3, d = 4](int mm) { return mm + a + b + c + d; };
  const auto large = [a = 1, b = 2, c = 3, d = 4, e = 5](int mm) { return mm + a + b + c + d + e; };
  const auto shared = [calibration = std::make_shared<int>(5)](int mm) { return mm + *calibration; };
  const std::function<int(int)> fs = small;
  const std::function<int(int)> fm = medium;
  const std::function<int(int)> fl = large;
  const std::function<int(int)> fp = shared;
  std::cout << std::format("sizeof(std::function<int(int)>) = {}\n", sizeof fs);
  std::cout << std::format("{:>2}-byte lambda inside: {}\n", sizeof small, stored_inside<decltype(small)>(fs));
  std::cout << std::format("{:>2}-byte lambda inside: {}\n", sizeof medium, stored_inside<decltype(medium)>(fm));
  std::cout << std::format("{:>2}-byte lambda inside: {}\n", sizeof large, stored_inside<decltype(large)>(fl));
  std::cout << std::format("{:>2}-byte lambda holding a shared_ptr inside: {}\n", sizeof shared,
                           stored_inside<decltype(shared)>(fp));
}
